'use strict';

// MODULES //

var assertSchema = require( '@data-apis/schema/assert' );
var canonicalStringify = require( '@data-apis/canonical/stringify' );


// FUNCTIONS //

/**
* Returns a source definition without its source-local identifier.
*
* @private
* @param {Object} source - source definition
* @returns {string} serialized endpoint definition
*/
function sourceIdentity( source ) {
	var copy = structuredClone( source );

	delete copy.id;
	return canonicalStringify( copy );
}


// MAIN //

/**
* Validates a registry value and cross-entry invariants.
*
* @param {Object} registry - registry value
* @returns {Object} validated registry
* @throws {Error} if validation fails
*/
function validateRegistry( registry ) {
	var libraryIds = new Set();

	assertSchema( 'registry-v1', registry );
	registry.libraries.forEach( function validateLibrary( library ) {
		var sourceIds = new Set();
		var sourceDefinitions = new Set();

		if ( libraryIds.has( library.id ) ) {
			throw new Error( 'Duplicate library id: ' + library.id );
		}
		libraryIds.add( library.id );
		library.sources.forEach( function validateSource( source ) {
			var identity;
			var url;

			if ( sourceIds.has( source.id ) ) {
				throw new Error( 'Duplicate source id ' + source.id + ' for ' + library.id );
			}
			sourceIds.add( source.id );
			identity = sourceIdentity( source );
			if ( sourceDefinitions.has( identity ) ) {
				throw new Error( 'Duplicate source definition for ' + library.id );
			}
			sourceDefinitions.add( identity );
			if ( source.type === 'url' ) {
				url = new URL( source.url );
				if ( url.protocol !== 'https:' ) {
					throw new Error( 'URL source ' + source.id + ' must use HTTPS' );
				}
				if ( url.username || url.password ) {
					throw new Error( 'URL source ' + source.id + ' must not contain credentials' );
				}
			}
		} );
	} );
	return registry;
}


// EXPORTS //

module.exports = validateRegistry;
